CREATE TABLE IF NOT EXISTS "SharedDish" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "familyId" uuid NOT NULL REFERENCES "Family"(id) ON DELETE CASCADE, "recipeKey" text NOT NULL, "createdByUserId" uuid NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, "createdAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, version int NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS "SharedDishPortion" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "sharedDishId" uuid NOT NULL REFERENCES "SharedDish"(id) ON DELETE CASCADE, "userId" uuid NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, servings decimal(10,2) NOT NULL, calories decimal(10,2) NOT NULL, "proteinG" decimal(10,2) NOT NULL, "fatG" decimal(10,2) NOT NULL, "carbsG" decimal(10,2) NOT NULL, UNIQUE("sharedDishId","userId"));
CREATE TABLE IF NOT EXISTS "FamilyShoppingList" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "familyId" uuid NOT NULL UNIQUE REFERENCES "Family"(id) ON DELETE CASCADE, version int NOT NULL DEFAULT 1, "regeneratedAt" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "regeneratedByUserId" uuid NOT NULL REFERENCES "User"(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS "FamilyShoppingItem" (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), "listId" uuid NOT NULL REFERENCES "FamilyShoppingList"(id) ON DELETE CASCADE, "productKey" text NOT NULL, name text NOT NULL, unit text NOT NULL, quantity decimal(12,3) NOT NULL, purchased boolean NOT NULL DEFAULT false, "forDishes" jsonb NOT NULL DEFAULT '[]'::jsonb);
